-- 0450 PROD CHECK, BEFORE the deploy AND AGAIN AFTER IT (the same read), read-only, ONE statement. GENERATED by gen-checks.mjs from the migration's own hunks.
--   npx --yes supabase@2.120.0 db query --linked --output-format json -f scripts/ops/harness/battle-stats/check.sql
-- Run scripts/ops/harness/db-health/gate.sql first (gate_ok true). One row, one jsonb column `r`. It reads the catalog (four function bodies), a dozen knobs,
-- public.battles of the last hour (RAID rows are kept 48 h; ~100 an hour) and the beat's ring. No big table is scanned; stable functions only.
-- BEFORE, wanted: head 20260818000449 (the migration before it); applied false; old: every count 1 (each old text once in the live body); new: every count 0;
--   knobs raid_flee_floor 0.1, raid_flee_max 0.8 and no flee_* / raid_flee_base; cards_1h 0. Write down raids_1h (outcomes, and of those that opened FLEE).
-- AFTER (30 minutes), wanted: head 20260818000450; applied true; new: every count 1; old {tick_fight.1: 0, tick_fight.2: 0, tick_fight.3: 0, tick_fight.4: 1, tick_fight.5: 0, tick_battle_run.1: 1, battle_ticks.1: 1, fight_card.1: 0, fight_card.2: 1} (an old text that stands inside its new text still counts 1);
--   knobs raid_flee_floor 0.03, raid_flee_max 0.45, raid_flee_base 0.1, flee_per_level 0.03, flee_level_max 0.15, flee_hurt_under 0.5, flee_hurt_max 0.2, flee_per_try 0.05;
--   cards_1h = every tick battle opened since the deploy (no_card only battles opened before it); sheet_kb mean about +1 to +2 over BEFORE, ticks_kb about +0.3;
--   raids_1h.flee: fewer EVADED, more PLUNDERED than BEFORE (the replay of 100 sheets: got away by running 15 of 39 before, 4 of 39 after; all raids EVADED 47 -> 36,
--   PLUNDERED 22 -> 32); rolls_pct: every roll within 3..45; stuck 0; span_s as before (max <= 75); beat < 1,000 ms and no worse than BEFORE.
-- ROLLBACK (the owner's knobs, the old chance to the digit): scripts/ops/harness/battle-stats/rollback-0450.sql.
begin transaction read only;
with hk(k, fn, old, neu) as (values
  ('tick_fight.1', 'public.tick_fight(uuid,jsonb,jsonb,jsonb)', E'  v_act    jsonb;\nbegin', E'  v_act    jsonb;\n  -- 0450: ESCAPING IS HARD. Each hull''s level and the crew she needs; each side''s failed attempts; the chance a run would roll now and where it\n  -- changed (`rc`); the knobs, read once a fight.\n  h_lvl    numeric[] := ''{}'';\n  h_need   numeric[] := ''{}'';\n  s_try    int[] := array[0, 0];\n  f_p      numeric[] := array[0, 0]::numeric[];\n  f_last   numeric[] := array[null, null]::numeric[];\n  f_lv     numeric[];\n  f_hull   numeric;\n  f_max    numeric;\n  f_crew   numeric;\n  f_need   numeric;\n  v_rc     jsonb[] := array[''[]''::jsonb, ''[]''::jsonb];\n  c_fbase  numeric := public.wc_num(''fight_flee_base'');\n  c_ffloor numeric := public.wc_num(''fight_flee_floor'');\n  c_emax   numeric := public.wc_num(''fight_evade_max'');\n  c_psight numeric := public.wc_num(''fight_evade_per_sighting'');\n  c_rbase  numeric := coalesce(public.wc_num(''raid_flee_base''), public.wc_num(''fight_flee_base''));\n  c_rfloor numeric := public.wc_num(''raid_flee_floor'');\n  c_rmax   numeric := public.wc_num(''raid_flee_max'');\n  c_plv    numeric := coalesce(public.wc_num(''flee_per_level''), 0);\n  c_lvmax  numeric := coalesce(public.wc_num(''flee_level_max''), 0);\n  c_hurt   numeric := coalesce(public.wc_num(''flee_hurt_max''), 0);\n  c_under  numeric := coalesce(public.wc_num(''flee_hurt_under''), 0);\n  c_ptry   numeric := coalesce(public.wc_num(''flee_per_try''), 0);\nbegin'),
  ('tick_fight.2', 'public.tick_fight(uuid,jsonb,jsonb,jsonb)', E'      h_wloss[n] := 0;\n      v_meta[s]  := v_meta[s] || jsonb_build_array(jsonb_build_object(''n'', x ->> ''name'', ''fl'', x ->> ''fleet_name'', ''h'', h_hull0[n], ''m'', h_maxd[n],\n                      ''t'', h_tier[n], ''r'', h_rel[n], ''f'', h_from[n], ''g'', h_att[n] > 0 and h_acc[n] > 0));', E'      h_wloss[n] := 0;\n      h_lvl[n]   := greatest(1, coalesce((x ->> ''lv'')::numeric, 1));          -- 0450: her level (public.battle_hull_card on the sheet; none: 1)\n      h_need[n]  := greatest(0, coalesce((x ->> ''crew_need'')::numeric, 0));   -- 0450: the crew her class needs (none on the sheet: her crew is never short)\n      v_meta[s]  := v_meta[s] || jsonb_build_array(jsonb_build_object(''n'', x ->> ''name'', ''fl'', x ->> ''fleet_name'', ''h'', h_hull0[n], ''m'', h_maxd[n],\n                      ''t'', h_tier[n], ''r'', h_rel[n], ''f'', h_from[n], ''g'', h_att[n] > 0 and h_acc[n] > 0, ''lv'', h_lvl[n]));'),
  ('tick_fight.3', 'public.tick_fight(uuid,jsonb,jsonb,jsonb)', E'      for s in 1 .. 2 loop\n        continue when s_run[s] <> t;\n        o := 3 - s;\n        v_p := case when s = 1 and p_opts ? ''a_flee''\n                    then least(public.wc_num(''raid_flee_max''), greatest(public.wc_num(''raid_flee_floor''),\n                           public.wc_num(''fight_flee_base'') + (s_sight[1] - s_sight[2]) * public.wc_num(''fight_evade_per_sighting'') + (p_opts ->> ''a_flee'')::numeric))\n                    else least(public.wc_num(''fight_evade_max''), greatest(public.wc_num(''fight_flee_floor''),\n                           public.wc_num(''fight_flee_base'') + (s_sight[s] - s_sight[o]) * public.wc_num(''fight_evade_per_sighting''))) end;', E'      -- 0450: THE CHANCE A RUN WOULD SLIP AWAY, each side, as the fight stands after this tick''s shots. ONE formula (the roll below reads it, and\n      -- `rc` serves it to the Run button): base + sighting lead + a raid''s a_flee (speed, handling) + the level difference - a crippled hull or a\n      -- short crew - her failed attempts, within the floor and the cap of its kind (a raid''s side set upon; any other run 0357''s).\n      f_lv := array[1, 1];\n      for i in 1 .. n loop\n        if h_up[i] then f_lv[h_side[i]] := greatest(f_lv[h_side[i]], h_lvl[i]); end if;\n      end loop;\n      for s in 1 .. 2 loop\n        o := 3 - s;\n        f_hull := 0; f_max := 0; f_crew := 0; f_need := 0;\n        for i in 1 .. n loop\n          if h_side[i] = s and h_up[i] then\n            f_hull := f_hull + h_hull[i]; f_max := f_max + h_maxd[i]; f_crew := f_crew + h_crew[i]; f_need := f_need + h_need[i];\n          end if;\n        end loop;\n        v_p := case when s = 1 and p_opts ? ''a_flee'' then c_rbase + (p_opts ->> ''a_flee'')::numeric else c_fbase end\n               + (s_sight[s] - s_sight[o]) * c_psight\n               + least(c_lvmax, greatest(-c_lvmax, (f_lv[s] - f_lv[o]) * c_plv))\n               - case when c_under > 0\n                      then c_hurt * greatest(0, 1 - least(case when f_max > 0 then f_hull / f_max else 1 end,\n                                                          case when f_need > 0 then f_crew / f_need else 1 end) / c_under)\n                      else 0 end\n               - s_try[s] * c_ptry;\n        f_p[s] := case when s = 1 and p_opts ? ''a_flee'' then least(c_rmax, greatest(c_rfloor, v_p)) else least(c_emax, greatest(c_ffloor, v_p)) end;\n        if round(f_p[s] * 100) is distinct from f_last[s] then\n          f_last[s] := round(f_p[s] * 100);\n          v_rc[s] := v_rc[s] || jsonb_build_array(jsonb_build_array(t, f_last[s]));\n        end if;\n      end loop;\n      for s in 1 .. 2 loop\n        continue when s_run[s] <> t;\n        o := 3 - s;\n        v_p := f_p[s];'),
  ('tick_fight.4', 'public.tick_fight(uuid,jsonb,jsonb,jsonb)', E'          s_run[s] := -1;', E'          s_run[s] := -1;\n          s_try[s] := s_try[s] + 1;   -- 0450: caught: her next attempt in this fight is flee_per_try worse'),
  ('tick_fight.5', 'public.tick_fight(uuid,jsonb,jsonb,jsonb)', E'    ''e'', v_ev, ''out'', v_outcome, ''r'', v_r);', E'    ''e'', v_ev, ''out'', v_outcome, ''r'', v_r,\n    ''rc'', jsonb_build_object(''a'', v_rc[1], ''b'', v_rc[2]));   -- 0450: each side''s run chance, [tick, per cent] where it changes'),
  ('tick_battle_run.1', 'public.tick_battle_run(uuid)', E'  select bs.fleet_id into v_att from public.battle_sides bs where bs.battle_id = p_battle and bs.side = ''ATTACKER'' and bs.how = ''OPENED'';', E'  -- 0450: EVERY HULL''S CARD (public.battle_hull_card: level, class, guns, crew she needs and may carry, speed, handling, fitted, captains), added\n  -- to a hull of the sheet that has none the first time she is run (the open; a joiner''s join) and frozen there: a re-run reads the sheet.\n  if exists (select 1 from jsonb_array_elements(coalesce(b.sheet -> ''a'', ''[]''::jsonb) || coalesce(b.sheet -> ''b'', ''[]''::jsonb)) e(h) where not (e.h ? ''lv'')) then\n    b.sheet := b.sheet || jsonb_build_object(\n      ''a'', (select coalesce(jsonb_agg(case when e.h ? ''lv'' then e.h else e.h || public.battle_hull_card((e.h ->> ''id'')::uuid) end order by e.o), ''[]''::jsonb)\n              from jsonb_array_elements(coalesce(b.sheet -> ''a'', ''[]''::jsonb)) with ordinality e(h, o)),\n      ''b'', (select coalesce(jsonb_agg(case when e.h ? ''lv'' then e.h else e.h || public.battle_hull_card((e.h ->> ''id'')::uuid) end order by e.o), ''[]''::jsonb)\n              from jsonb_array_elements(coalesce(b.sheet -> ''b'', ''[]''::jsonb)) with ordinality e(h, o)));\n    update public.battles set sheet = b.sheet where id = p_battle;\n  end if;\n  select bs.fleet_id into v_att from public.battle_sides bs where bs.battle_id = p_battle and bs.side = ''ATTACKER'' and bs.how = ''OPENED'';'),
  ('battle_ticks.1', 'world.battle_ticks(uuid)', E'    ''mine'', v_mine,', E'    ''mine'', v_mine,\n    -- 0450: every hull of the sheet as it was frozen, in the timeline''s order (a, b): what the fight fights with, and her card\n    ''ships'', jsonb_build_object(\n      ''a'', (select coalesce(jsonb_agg(e.h - ''id'' - ''boarder_pct'' order by e.o), ''[]''::jsonb) from jsonb_array_elements(coalesce(b.sheet -> ''a'', ''[]''::jsonb)) with ordinality e(h, o)),\n      ''b'', (select coalesce(jsonb_agg(e.h - ''id'' - ''boarder_pct'' order by e.o), ''[]''::jsonb) from jsonb_array_elements(coalesce(b.sheet -> ''b'', ''[]''::jsonb)) with ordinality e(h, o))),'),
  ('fight_card.1', 'public.fight_card(uuid,uuid)', E'                ''nation'', x.nation, ''ships'', x.ships, ''here'', x.here)', E'                ''nation'', x.nation, ''ships'', x.ships, ''lv'', x.lv, ''here'', x.here)   -- 0450: lv, her fleet''s best level'),
  ('fight_card.2', 'public.fight_card(uuid,uuid)', E'                    (select count(*) from public.ships sh where sh.fleet_id = f.id)::int as ships,', E'                    (select count(*) from public.ships sh where sh.fleet_id = f.id)::int as ships,\n                    (select coalesce(max(public.ship_level(sh.id)), 1) from public.ships sh where sh.fleet_id = f.id)::int as lv,   -- 0450')
), body as (
  select f.fn, replace(pg_get_functiondef(f.fn::regprocedure), E'\r', '') as def
    from (values ('public.tick_fight(uuid,jsonb,jsonb,jsonb)'), ('public.tick_battle_run(uuid)'), ('world.battle_ticks(uuid)'), ('public.fight_card(uuid,uuid)')) f(fn)
), b as (
  select x.id, x.kind, x.status, x.started_at, x.resolves_at, x.result, x.sheet, x.ticks
    from public.battles x where x.started_at > now() - interval '1 hour' and x.ticks is not null and x.ticks <> 'null'::jsonb
)
select jsonb_build_object(
  'at', now(),
  'head', (select max(m.version) from supabase_migrations.schema_migrations m),
  'applied', to_regprocedure('public.battle_hull_card(uuid)') is not null,
  'old', (select jsonb_object_agg(hk.k, (length(body.def) - length(replace(body.def, hk.old, ''))) / length(hk.old)) from hk join body on body.fn = hk.fn),
  'new', (select jsonb_object_agg(hk.k, (length(body.def) - length(replace(body.def, hk.neu, ''))) / length(hk.neu)) from hk join body on body.fn = hk.fn),
  'bodies', (select jsonb_object_agg(body.fn, md5(body.def)) from body),
  'volatility', (select jsonb_object_agg(p.oid::regprocedure::text, p.provolatile) from pg_proc p
                  where p.oid in ('public.fleet_kind(uuid)'::regprocedure, 'public.level_in_force(numeric)'::regprocedure, 'world.ship_stats(uuid)'::regprocedure,
                                  'public.ship_base(uuid)'::regprocedure, 'public.captain_level(uuid,text)'::regprocedure)),
  'knobs', (select jsonb_object_agg(k.key, k.value) from public.world_config k
             where k.key ~ '^(raid_flee|flee_)' or k.key in ('fight_flee_base', 'fight_flee_floor', 'fight_evade_max', 'fight_evade_per_sighting', 'levels_bite',
                                                                             'npc_ship_level', 'tick_fight_kinds', 'ship_level_accuracy_per_level', 'ship_level_sighting_per_level')),
  'tick_1h', (select count(*) from b),
  'cards_1h', (select count(*) from b where not exists (select 1 from jsonb_array_elements(coalesce(b.sheet -> 'a', '[]'::jsonb) || coalesce(b.sheet -> 'b', '[]'::jsonb)) h where not (h ? 'lv'))),
  'no_card_newest', (select max(b.started_at) from b where exists (select 1 from jsonb_array_elements(coalesce(b.sheet -> 'a', '[]'::jsonb) || coalesce(b.sheet -> 'b', '[]'::jsonb)) h where not (h ? 'lv'))),
  'sheet_kb', (select round(avg(length(b.sheet::text)) / 1024.0, 2) from b),
  'ticks_kb', (select round(avg(length(b.ticks::text)) / 1024.0, 2) from b),
  'raids_1h', (select jsonb_build_object(
                 'all', (select coalesce(jsonb_object_agg(z.o, z.n), '{}'::jsonb) from (select coalesce(b.ticks ->> 'out', '-') as o, count(*) as n from b where b.kind = 'RAID' group by 1) z),
                 'flee', (select coalesce(jsonb_object_agg(z.o, z.n), '{}'::jsonb) from (select coalesce(b.ticks ->> 'out', '-') as o, count(*) as n from b where b.kind = 'RAID' and b.ticks #>> '{ai,a}' = 'FLEE' group by 1) z),
                 'fled', (select count(*) from b where b.kind = 'RAID' and coalesce((b.ticks #>> '{r,fled}')::boolean, false)))),
  'rolls_pct', (select jsonb_build_object('n', count(*), 'min', min((e ->> 3)::numeric), 'max', max((e ->> 3)::numeric), 'away', count(*) filter (where e ->> 4 = '1'))
                  from b cross join lateral jsonb_array_elements(b.ticks -> 'e') e where b.kind = 'RAID' and e ->> 2 = 'X' and e ->> 1 = '0'),
  'span_s', (select jsonb_build_object('mean', round(avg(extract(epoch from b.resolves_at - b.started_at))), 'max', round(max(extract(epoch from b.resolves_at - b.started_at)))) from b),
  'stuck', (select count(*) from b where b.status = 'FIGHTING' and b.resolves_at < now() - interval '2 minutes'),
  'beat', (select jsonb_build_object('mean_ms', round(avg(a.ms)), 'n', count(*)) from public.arrivals_beats a where a.at > now() - interval '5 minutes')
) as r;
commit;
